// A code component draws anything into its element; props are the bindings prop: of the Logic tab, ctx.emit(event, data) fires the element’s events
export default {
  mount(el, props, ctx) {
    const box = document.createElement('div');
    box.textContent = props.text ?? 'Component';
    el.replaceChildren(box);
    return {
      update(next) { box.textContent = next.text ?? 'Component'; },
      destroy() {},
    };
  },
};
